package ro.leo.visual;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.Bundle;import android.provider.MediaStore;import android.text.InputType;import android.widget.*;import java.util.*;import java.io.*;
/** Edits playlist references only, never the original songs. */
public final class PlaylistEditorActivity extends LeoActivity {
 private String name;private ArrayList<String[]> rows;private int selected,generation;
 protected void onCreate(Bundle b){super.onCreate(b);name=b==null?getIntent().getStringExtra("name"):b.getString("name");reload();}
 protected void onSaveInstanceState(Bundle b){b.putString("name",name);super.onSaveInstanceState(b);}
 private void reload(){rows=MusicLists.read(this).get(name);if(rows==null){notice("Lista nu mai există");finish();return;}show();}
 private boolean save(){TreeMap<String,ArrayList<String[]>> lists=MusicLists.read(this);if(!lists.containsKey(name)){notice("Lista nu mai există");finish();return false;}lists.put(name,rows);if(!MusicLists.write(this,lists)){notice("Salvare nereușită");reload();return false;}return true;}
 private void show(){generation++;ArrayList<String> labels=new ArrayList<String>();for(String[] r:rows)labels.add(r[1]);list(name,labels,Math.min(selected,Math.max(0,rows.size()-1)),new Choice(){public void pick(final int at){selected=at;options(rows.get(at)[1],new String[]{"Mută mai sus","Mută mai jos","Elimină din listă"},new Choice(){public void pick(int i){if(i==2)rows.remove(at);else{int to=CircularNavigation.step(at,i==0?-1:1,rows.size());Collections.swap(rows,at,to);selected=to;}if(save())show();}});}},"Opțiuni",new Runnable(){public void run(){options("Lista · "+name,new String[]{"Adaugă o piesă","Redenumește lista","Verifică referințe lipsă","Alege copertă","Elimină coperta"},new Choice(){public void pick(int i){if(i==0)add();else if(i==1)rename();else if(i==2)check();else if(i==3)startActivityForResult(new Intent(PlaylistEditorActivity.this,GalleryActivity.class).putExtra("pick_image",true),71);else{getSharedPreferences("playlist-art",0).edit().remove(name).apply();worker.execute(new Runnable(){public void run(){cleanCovers();}});notice("Copertă eliminată");}}});}});}
 private void rename(){generation++;LinearLayout f=fields("Redenumește lista");final EditText value=field(f,"Nume",name,InputType.TYPE_CLASS_TEXT);value.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(40)});left=new Runnable(){public void run(){String next=value.getText().toString().trim();TreeMap<String,ArrayList<String[]>> lists=MusicLists.read(PlaylistEditorActivity.this);if(next.isEmpty()||!next.equals(name)&&lists.containsKey(next)){notice("Alege un nume liber");return;}if(!lists.containsKey(name)){reload();return;}lists.remove(name);lists.put(next,rows);if(!MusicLists.write(PlaylistEditorActivity.this,lists)){notice("Salvare nereușită");return;}String art=getSharedPreferences("playlist-art",0).getString(name,null);SharedPreferences.Editor e=getSharedPreferences("playlist-art",0).edit().remove(name);if(art!=null)e.putString(next,art);e.apply();name=next;show();}};back=new Runnable(){public void run(){show();}};footer("Salvează","Editor","Șterge");value.requestFocus();}
 private void add(){final int token=++generation;if(rows.size()>=500){notice("Maximum 500 piese");return;}worker.execute(new Runnable(){public void run(){final ArrayList<String[]> found=new ArrayList<String[]>();try(Cursor c=getContentResolver().query(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,new String[]{"_id","title"},null,null,"title COLLATE NOCASE")){while(c!=null&&c.moveToNext()&&found.size()<500)found.add(new String[]{ContentUris.withAppendedId(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,c.getLong(0)).toString(),c.getString(1)==null?"Piesă":c.getString(1)});}catch(RuntimeException e){}ui(new Runnable(){public void run(){if(token!=generation)return;ArrayList<String> labels=new ArrayList<String>();for(String[] t:found)labels.add(t[1]);list("Adaugă în listă",labels,0,new Choice(){public void pick(int i){rows.add(found.get(i));if(save()){selected=rows.size()-1;show();}}},"Înapoi",new Runnable(){public void run(){show();}});back=new Runnable(){public void run(){show();}};}});}});}
 private void check(){final int token=++generation;final ArrayList<String[]> snapshot=new ArrayList<String[]>(rows);worker.execute(new Runnable(){public void run(){final ArrayList<String[]> missing=new ArrayList<String[]>();int denied=0;for(String[] row:snapshot){try(android.os.ParcelFileDescriptor fd=getContentResolver().openFileDescriptor(Uri.parse(row[0]),"r")){if(fd==null)denied++;}catch(FileNotFoundException e){missing.add(row);}catch(Exception e){denied++;}}final int unknown=denied;ui(new Runnable(){public void run(){if(token!=generation)return;options("Lipsă: "+missing.size()+" · necunoscut: "+unknown,new String[]{"Păstrează tot · cardul poate fi scos","Elimină doar referințele lipsă"},new Choice(){public void pick(int yes){if(yes==1){rows.removeAll(missing);if(save())show();}}});}});}});}
 private void cleanCovers(){Set<String> used=new HashSet<String>();for(Object value:getSharedPreferences("playlist-art",0).getAll().values())if(value instanceof String)used.add((String)value);File[] files=new File(getFilesDir(),"playlist-covers").listFiles();if(files!=null)for(File f:files)if(f.getName().matches("cover-[A-Za-z0-9_-]+\\.jpg")&&!used.contains(f.getName()))f.delete();}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==71&&result==RESULT_OK&&data!=null&&data.getData()!=null){final Uri uri=data.getData();final String key=name;worker.execute(new Runnable(){public void run(){try{android.graphics.Bitmap image=Appearance.decode(PlaylistEditorActivity.this,uri,192);File dir=new File(getFilesDir(),"playlist-covers");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException();File f=File.createTempFile("cover-",".jpg",dir);try(FileOutputStream out=new FileOutputStream(f)){if(!image.compress(android.graphics.Bitmap.CompressFormat.JPEG,85,out))throw new IOException();}finally{image.recycle();}if(!getSharedPreferences("playlist-art",0).edit().putString(key,f.getName()).commit())throw new IOException();cleanCovers();ui(new Runnable(){public void run(){notice("Copertă salvată pentru listă");show();}});}catch(Exception|OutOfMemoryError e){ui(new Runnable(){public void run(){notice("Coperta nu poate fi citită");}});}}});}}
}
